<script lang="ts">
 import AppSelect from "../components/Select.svelte";
 import {onMount} from 'svelte';
 import QRCode from 'qrcode';
 import Icon from '../components/Icon.svelte';
 import Modal from '../components/Modal.svelte';
 import CountryBadge from '../components/CountryBadge.svelte';
 import {api,demo,copy,download,errorMessage,toast} from '../store.svelte';
 import {nodeProtocol,nodeAddress} from '../node-workbench';
 import type {Row} from '../data';

 type Category={id:string;name:string;policy:string;rules:string[];recommended:boolean};
 let nodes=$state<Row[]>([]),categories=$state<Category[]>([]),links=$state<Row[]>([]),templates=$state<Row[]>([]);
 let selected=$state<string[]>([]),ruleIDs=$state<string[]>([]),subscriptionId=$state(''),format=$state('clash'),mode=$state('custom'),templateId=$state('');
 let query=$state(''),protocol=$state(''),tag=$state(''),preset=$state('balanced'),name=$state(''),days=$state(7);
 let loading=$state(true),busy=$state(false),error=$state(''),result=$state<any>(null),qr=$state(''),outputOpen=$state(false),outputTab=$state('config'),revokeTarget=$state<Row|null>(null),revokeOpen=$state(false);
 let request=0;
 const tagsOf=(row:Row):string[]=>Array.isArray(row.tags)?row.tags:String(row.tags??'').split(/[,，]+/).map(value=>value.trim()).filter(Boolean);
 const protocols=$derived([...new Set(nodes.map(nodeProtocol))]);
 const tags=$derived([...new Set(nodes.flatMap(tagsOf))]);
 const filtered=$derived(nodes.filter(row=>(!protocol||nodeProtocol(row)===protocol)&&(!tag||tagsOf(row).includes(tag))&&(!query||[row.name,nodeAddress(row),...tagsOf(row)].join(' ').toLowerCase().includes(query.toLowerCase()))));
 const selectable=$derived(filtered.filter(row=>row.formats?.includes(format)));
 const matchingTemplates=$derived(templates.filter(row=>String(row.type).toLowerCase()===format));
 const payload=$derived({name,nodeIds:selected,subscriptionId,format,mode,templateId:mode==='template'?templateId:'',categories:mode==='custom'?ruleIDs:[],expiresInDays:days});
 const signature=$derived(JSON.stringify(payload));
 const ready=$derived(result?.signature===signature);
 const valid=$derived(selected.length>0&&selected.length<=500&&selected.every(id=>nodes.some(row=>row.id===id&&row.formats?.includes(format)))&&(mode!=='template'||matchingTemplates.some(row=>row.id===templateId)));
 const policies:Record<string,string>={ASWired:'代理',DIRECT:'直连',REJECT:'拦截'};
 onMount(()=>{void load(true);return()=>{request++;};});
 async function load(initial=false){const current=++request;loading=true;error='';try{const [data,choices]=await Promise.all([api(`/api/subscription-generator?subscriptionId=${encodeURIComponent(subscriptionId)}`),api('/api/templates/options')]);if(current!==request)return;nodes=data.nodes;categories=data.categories;links=data.links;templates=choices.templates;selected=selected.filter(id=>nodes.some(row=>row.id===id));if(initial){applyPreset('balanced');const ids=new URL(location.href).searchParams.getAll('node');selected=ids.filter(id=>nodes.some(row=>row.id===id));}}catch(cause){if(current===request){nodes=[];selected=[];error=errorMessage(cause);}}finally{if(current===request)loading=false;}}
 function applyPreset(value:string){preset=value;ruleIDs=categories.filter(item=>value==='all'||value==='balanced'&&item.recommended||value==='minimal'&&['private','china'].includes(item.id)).map(item=>item.id);}
 function toggleRule(id:string){preset='custom';ruleIDs=ruleIDs.includes(id)?ruleIDs.filter(value=>value!==id):[...ruleIDs,id];}
 function toggle(id:string){selected=selected.includes(id)?selected.filter(value=>value!==id):[...selected,id];}
 function selectFiltered(){const ids=selectable.map(row=>row.id);selected=ids.every(id=>selected.includes(id))?selected.filter(id=>!ids.includes(id)):[...new Set([...selected,...ids])];}
 function changeFormat(){templateId='';result=null;qr='';}
 function clear(){selected=[];query='';protocol='';tag='';name='';result=null;qr='';error='';}
 async function generate(createLink=false){if(busy||loading||!valid)return;busy=true;error='';const stamp=signature;const input={...payload,createLink};try{const data=await api('/api/subscription-generator',{method:'POST',body:JSON.stringify(input)});if(data.row)links=[data.row,...links];if(stamp!==signature)return;result={...data,signature:stamp,url:data.url?new URL(data.url,location.origin).href:''};outputTab=createLink?'link':'config';qr='';outputOpen=true;if(result.url){try{const image=await QRCode.toDataURL(result.url,{width:192,margin:2});if(result?.signature===stamp)qr=image;}catch{toast('二维码生成失败，可复制订阅链接');}}}catch(cause){error=errorMessage(cause);}finally{busy=false;}}
 async function revoke(){if(!revokeTarget||busy)return;busy=true;error='';try{await api(`/api/subscription-generator/${encodeURIComponent(revokeTarget.id)}`,{method:'DELETE'});links=links.map(row=>row.id===revokeTarget!.id?{...row,revoked:true}:row);if(result?.row?.id===revokeTarget.id)result=null;revokeOpen=false;toast('订阅链接已撤销');}catch(cause){error=errorMessage(cause);}finally{busy=false;}}
 function status(row:Row){return row.revoked?'已撤销':Date.parse(row.expiresAt)<=Date.now()?'已到期':'有效';}
</script>

<div class="page-head"><h1><Icon name="rss" size={24}/>生成订阅</h1><div class="actions"><a class="button" href="/templates"><Icon name="code"/>模板管理</a><button class="icon-button" title="刷新节点" aria-label="刷新节点" disabled={loading||busy} onclick={()=>load()}><Icon name="refresh"/></button></div></div>
{#if error&&!revokeOpen}<p class="error" role="alert">{error}</p>{/if}
<fieldset class="generator" disabled={loading||busy}>
 <div class="settings-row"><label class="field">节点范围<AppSelect bind:value={subscriptionId} onchange={()=>{selected=[];result=null;void load();}} aria-label="节点范围" options={[{value:'',label:'节点库 · 外部及手动节点'},...demo.data.subscriptions.map(sub=>({value:sub.id,label:sub.name+' · '+(sub.member??sub.plan??'')}))]}/></label><label class="field">客户端格式<AppSelect bind:value={format} onchange={changeFormat} aria-label="生成客户端格式" options={[{value:'clash',label:'Clash / Mihomo'},{value:'surge',label:'Surge'},{value:'loon',label:'Loon'}]}/></label></div>
 <section class="generator-section" aria-label="选择节点"><div class="section-title"><h2>选择节点 <small>已选 {selected.length}</small></h2><div class="search-input"><Icon name="search"/><input bind:value={query} placeholder="搜索节点名称或地址" aria-label="搜索生成节点"/></div></div>
 <div class="filter-row" role="group" aria-label="协议筛选"><button type="button" class:active={!protocol} aria-pressed={!protocol} onclick={()=>protocol=''}>全部 ({nodes.length})</button>{#each protocols as item}<button type="button" class:active={protocol===item} aria-pressed={protocol===item} onclick={()=>protocol=item}>{item} ({nodes.filter(row=>nodeProtocol(row)===item).length})</button>{/each}</div>
 {#if tags.length}<div class="filter-row tags" role="group" aria-label="标签筛选"><button type="button" class:active={!tag} aria-pressed={!tag} onclick={()=>tag=''}>全部标签 ({nodes.length})</button>{#each tags as item}<button type="button" class:active={tag===item} aria-pressed={tag===item} onclick={()=>tag=item}>{item} ({nodes.filter(row=>tagsOf(row).includes(item)).length})</button>{/each}</div>{/if}
 <div class="node-table"><table aria-label="可生成订阅的节点"><thead><tr><th class="check-cell"><input type="checkbox" aria-label="选择筛选结果" checked={selectable.length>0&&selectable.every(row=>selected.includes(row.id))} indeterminate={selectable.some(row=>selected.includes(row.id))&&!selectable.every(row=>selected.includes(row.id))} disabled={!selectable.length} onchange={selectFiltered}/></th><th>节点名称</th><th>协议</th><th>服务器地址</th></tr></thead><tbody>{#each filtered as row (row.id)}<tr class:selected={selected.includes(row.id)} class:unavailable={!row.formats?.includes(format)}><td><input type="checkbox" aria-label={`选择 ${row.name}`} checked={selected.includes(row.id)} disabled={!row.formats?.includes(format)} onchange={()=>toggle(row.id)}/></td><td><div class="node-name"><CountryBadge region={row.region}/><span>{row.name}</span></div>{#if !row.formats?.includes(format)}<small class="muted">{row.error||'不兼容当前客户端'}</small>{/if}</td><td><span class="tag">{nodeProtocol(row)}</span></td><td><code>{nodeAddress(row)}</code></td></tr>{:else}<tr><td colspan="4"><div class="empty">{loading?'正在读取节点…':query||protocol||tag?'没有匹配的节点':'暂无可用节点'}</div></td></tr>{/each}</tbody></table></div>
 <div class="selection-bar"><span>筛选 {filtered.length} 个 · 可选 {selectable.length} 个</span><button type="button" class="quiet-button" disabled={!selected.length} onclick={()=>selected=[]}>取消选择</button></div></section>

 <section class="generator-section" aria-label="订阅规则"><h2>规则模式</h2><div class="mode-tabs" role="tablist" aria-label="规则模式"><button type="button" role="tab" aria-selected={mode==='custom'} class:active={mode==='custom'} onclick={()=>mode='custom'}><Icon name="sliders"/>自定义规则</button><button type="button" role="tab" aria-selected={mode==='template'} class:active={mode==='template'} onclick={()=>mode='template'}><Icon name="code"/>使用模板</button></div>
 {#if mode==='custom'}<label class="field">规则选择<AppSelect aria-label="规则预设" value={preset} onchange={applyPreset} options={[{value:'balanced',label:'均衡规则'},{value:'minimal',label:'精简规则'},{value:'all',label:'全部规则'},{value:'none',label:'无分类规则'},...(preset==='custom'?[{value:'custom',label:'自定义'}]:[])]}/></label><details class="rule-details" open><summary>已选择 {ruleIDs.length} 个类别</summary><div class="rule-grid">{#each categories as category}<label class="rule-option" title={category.rules.join('\n')}><input type="checkbox" checked={ruleIDs.includes(category.id)} onchange={()=>toggleRule(category.id)}/><span>{category.name}</span><small class:block-policy={category.policy==='REJECT'}>{policies[category.policy]}</small></label>{/each}</div></details>
 {:else}<label class="field">订阅模板<AppSelect bind:value={templateId} aria-label="生成订阅模板" options={[{value:'',label:'选择模板'},...matchingTemplates.map(template=>({value:template.id,label:template.name+(template.isDefault?' · 默认':'')}))]}/></label>{#if !matchingTemplates.length}<div class="template-empty">暂无匹配的模板 <a href="/templates">新建模板 <Icon name="arrow" size={14}/></a></div>{/if}{/if}</section>

 <section class="generator-section output-settings" aria-label="生成设置"><div class="settings-row"><label class="field">订阅名称<input bind:value={name} maxlength="100" placeholder="ASWired" aria-label="生成订阅名称"/></label><label class="field">链接有效期<AppSelect value={String(days)} onchange={value=>days=Number(value)} aria-label="链接有效期" options={[1,7,30,90].map(value=>({value:String(value),label:value+' 天'}))}/></label></div><div class="generate-actions"><button class="button primary" disabled={!valid} onclick={()=>generate()}><Icon name="file"/>{busy?'生成中…':'生成订阅文件'}</button><button class="button" disabled={!valid} onclick={()=>generate(true)}><Icon name="link"/>创建订阅链接</button><button class="icon-button" title="清空选择" aria-label="清空选择" onclick={clear}><Icon name="trash"/></button></div>{#if selected.length>500}<p class="error">每次最多选择 500 个节点</p>{/if}</section>
</fieldset>

{#if links.length}<section class="generated-history"><div class="section-title"><h2>已生成链接</h2><span class="muted">{links.length} 条</span></div><div class="table-scroll"><table aria-label="已生成订阅链接"><thead><tr><th>名称</th><th>格式 / 节点</th><th>到期时间</th><th>状态</th><th></th></tr></thead><tbody>{#each links as row}<tr><td>{row.name}</td><td>{String(row.format).toUpperCase()} · {row.nodeCount}</td><td>{new Date(row.expiresAt).toLocaleString('zh-CN')}</td><td>{status(row)}</td><td><button class="icon-button" title="撤销链接" aria-label={`撤销 ${row.name}`} disabled={busy||status(row)!=='有效'} onclick={()=>{revokeTarget=row;error='';revokeOpen=true;}}><Icon name="unplug"/></button></td></tr>{/each}</tbody></table></div></section>{/if}

<Modal bind:open={outputOpen} title="订阅已生成" wide>{#if ready}<div class="output-heading"><span>{result.nodeCount} 个节点 · {format.toUpperCase()}</span><div class="tabs"><button class:active={outputTab==='config'} onclick={()=>outputTab='config'}>配置预览</button>{#if result.url}<button class:active={outputTab==='link'} onclick={()=>outputTab='link'}>订阅链接</button>{/if}</div></div>{#if outputTab==='link'}<label class="field">订阅链接<input readonly value={result.url} aria-label="生成的订阅链接"/></label><div class="qr-output">{#if qr}<img src={qr} width="192" height="192" alt="生成订阅二维码"/>{/if}<small>到期时间：{new Date(result.row.expiresAt).toLocaleString('zh-CN')}</small></div>{:else}<textarea readonly class="config-preview" aria-label="生成的订阅配置" value={result.content}></textarea>{/if}<div class="modal-actions"><button class="button" onclick={()=>outputOpen=false}>关闭</button><button class="button" onclick={()=>copy(outputTab==='link'?result.url:result.content)}><Icon name="copy"/>{outputTab==='link'?'复制链接':'复制配置'}</button><button class="button primary" onclick={()=>download(result.filename,result.content,result.mime)}><Icon name="download"/>下载配置</button></div>{:else}<p class="error">生成选项已改变，请重新生成。</p><div class="modal-actions"><button class="button" onclick={()=>outputOpen=false}>关闭</button></div>{/if}</Modal>
<Modal bind:open={revokeOpen} title="撤销订阅链接"><p>撤销「{revokeTarget?.name}」后，该链接将立即失效。</p>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="modal-actions"><button class="button" disabled={busy} onclick={()=>revokeOpen=false}>取消</button><button class="button danger" disabled={busy} onclick={revoke}>撤销链接</button></div></Modal>

<style>
 h1{display:flex;align-items:center;gap:.65rem;font-size:1.45rem;letter-spacing:0}h2{font-size:.94rem;letter-spacing:0}.generator{border:0;padding:0;margin:0;min-width:0}.generator:disabled{opacity:.7}.settings-row{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:1rem}.generator-section{padding:1.2rem 0;border-bottom:1px solid var(--line)}.section-title{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-bottom:.8rem}.section-title h2 small{font-weight:400;color:var(--muted);margin-left:.6rem}.search-input{width:260px;max-width:100%}.filter-row{display:flex;flex-wrap:wrap;gap:.4rem;margin:.7rem 0}.filter-row button{font-size:.75rem;color:var(--muted);border:1px solid var(--line);border-radius:4px;background:var(--background);padding:.42rem .65rem;overflow-wrap:anywhere;text-align:left}.filter-row button.active{color:var(--primary);border-color:var(--primary);background:color-mix(in srgb,var(--primary) 12%,var(--background))}.node-table{max-height:410px;overflow:auto;border:1px solid var(--line);background:var(--card)}table{width:100%;border-collapse:collapse}.node-table table{min-width:620px}.node-table th{position:sticky;top:0;z-index:1;background:var(--background)}td,th{padding:.7rem .75rem;text-align:left;font-size:.8rem}.check-cell{width:38px}.node-name{display:flex;align-items:center;gap:.5rem;overflow-wrap:anywhere;min-width:0}.node-table td:nth-child(2){min-width:180px;max-width:460px}.node-table code{font-size:.75rem;overflow-wrap:anywhere}.selected{background:color-mix(in srgb,var(--primary) 8%,transparent)}.unavailable{opacity:.6}.selection-bar{display:flex;align-items:center;justify-content:space-between;margin-top:.6rem;font-size:.75rem;color:var(--muted)}.quiet-button{background:none;border:0;color:var(--primary);font-size:.75rem;padding:.3rem}.mode-tabs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.5rem;margin:.85rem 0}.mode-tabs button{display:flex;align-items:center;justify-content:center;gap:.5rem;min-height:38px;border:1px solid var(--line);border-radius:4px;background:var(--background);color:var(--muted);font-size:.8rem}.mode-tabs button.active{color:var(--primary);border-color:var(--primary);background:color-mix(in srgb,var(--primary) 12%,var(--background))}.rule-details{margin-top:1rem;background:var(--card);border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:.9rem}.rule-details summary{font-size:.8rem;cursor:pointer}.rule-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.7rem 2rem;margin-top:1rem}.rule-option{display:flex;align-items:center;gap:.55rem;min-width:0;font-size:.82rem}.rule-option span{flex:1;overflow-wrap:anywhere}.rule-option small{font-size:.67rem;color:var(--muted)}.rule-option small.block-policy{color:var(--danger)}.rule-option input{flex-shrink:0}.generate-actions{display:flex;gap:.6rem;margin-top:1rem}.generate-actions>.primary{flex:1}.template-empty{display:flex;align-items:center;gap:.7rem;color:var(--muted);font-size:.8rem;padding:1rem 0}.template-empty a{display:flex;align-items:center;gap:.3rem}.generated-history{margin-top:1.5rem}.generated-history table{min-width:580px}.config-preview{display:block;resize:vertical;width:100%;height:400px;max-height:55dvh;background:var(--background);color:var(--foreground);border:1px solid var(--line);border-radius:4px;font:.77rem/1.7 ui-monospace,Consolas,monospace;white-space:pre;overflow:auto;padding:1rem}.output-heading>span{font-size:.8rem;color:var(--muted)}.qr-output{display:flex;align-items:center;flex-direction:column;gap:.8rem;padding:1.2rem 0}.qr-output small{font-size:.75rem;color:var(--muted)}
 @media(max-width:767px){h1{font-size:1.2rem}.page-head{flex-wrap:wrap}.settings-row{grid-template-columns:1fr}.section-title{flex-wrap:wrap}.search-input{width:100%}.rule-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:.8rem}.generate-actions{flex-wrap:wrap}.generate-actions>.primary{flex-basis:100%}.node-table{max-height:350px}.rule-option{font-size:.76rem}.rule-details{padding:.75rem}.modal-actions{flex-wrap:wrap}}
 @media(max-width:360px){.rule-grid{grid-template-columns:1fr}}
</style>
